async function loadTxdotSourcesFromOpenData() {
  const districtsRaw = process.env.CCTV_TXDOT_DISTRICTS ?? DEFAULT_TXDOT_DISTRICTS;
  const districts = [
    ...new Set(
      String(districtsRaw).split(",").map((token) => token.trim().toUpperCase()).filter((code) => TXDOT_DISTRICTS.has(code))
    )
  ];
  if (!districts.length) return [];
  const settled = await Promise.allSettled(
    districts.map(async (district) => {
      const resp = await fetch(TXDOT_CCTV_STATUS_URL(district), {
        headers: {
          Accept: "application/json",
          "User-Agent": "odin-cctv-proxy/1.0"
        },
        signal: AbortSignal.timeout(CCTV_SOURCE_FETCH_TIMEOUT_MS)
      });
      if (!resp.ok) throw new Error(`${district} HTTP ${resp.status}`);
      return { district, payload: await resp.json() };
    })
  );
  const cameras = [];
  for (const result of settled) {
    if (result.status !== "fulfilled") {
      console.warn(
        "[CCTV] TxDOT district fetch failed:",
        result.reason?.message || result.reason
      );
      continue;
    }
    cameras.push(
      ...normalizeTxdotDistrictPayload(
        result.value.payload,
        result.value.district
      )
    );
  }
  const maxRaw = Number(
    process.env.CCTV_TXDOT_MAX_SOURCES || DEFAULT_TXDOT_MAX_SOURCES
  );
  const maxCount = Number.isFinite(maxRaw) ? Math.max(8, Math.min(2e3, Math.floor(maxRaw))) : DEFAULT_TXDOT_MAX_SOURCES;
  const prioritized = prioritizeSources(cameras, maxCount, TXDOT_ANCHORS);
  console.log(
    `[CCTV] Loaded TxDOT camera sources: ${cameras.length} online across ${districts.join(",")} (using nearest ${prioritized.length})`
  );
  return prioritized;
}
