function parseTleText(text7) {
  const lines = String(text7).trim().split("\n").map((line) => line.trim()).filter((line) => line.length > 0);
  const result = [];
  for (let i = 0; i < lines.length - 2; i++) {
    const name = lines[i];
    const line1 = lines[i + 1];
    const line2 = lines[i + 2];
    const cat1 = tleCatalogNumber(line1);
    const cat2 = tleCatalogNumber(line2);
    if (line1.startsWith("1 ") && line2.startsWith("2 ") && cat1 !== null && cat1 === cat2) {
      result.push({ name, line1, line2 });
      i += 2;
    }
  }
  return result;
}
