// src/tools/functions.js
function toFunctionTools(tools, { exclude = [] } = {}) {
  const skipped = new Set(exclude);
  return tools.filter((tool) => !skipped.has(tool.name)).map((tool) => ({
    type: "function",
    name: tool.name,
    description: tool.description,
    parameters: structuredClone(tool.inputSchema)
  }));
}

